-- ==========================================================================
-- PLN DIGI - DATA DUMMY 50 USERS & SKENARIO LENGKAP
-- Digunakan untuk testing, presentasi lomba, dan transfer via GitHub
-- Tanggal Ekspor: 2026-09-28 09:42:06
-- Default Password untuk semua akun dummy: 'password'
-- ==========================================================================

SET FOREIGN_KEY_CHECKS=0;

-- --------------------------------------------------------------------------
-- 1. TABEL: users (50 Akun Pengguna)
-- Ringkasan Kasus:
--  * No 1 - 10 : Pascabayar Tertib (2 tagihan lunas, 1 belum bayar)
--  * No 11 - 18: Pascabayar Menunggak / Overdue (denda keterlambatan)
--  * No 19 - 26: Prabayar Token Aktif (riwayat transaksi token 20 digit)
--  * No 27 - 32: User Baru / Fresh Onboarding (belum mendaftarkan ID Pelanggan)
--  * No 33 - 38: Catat Meter Mandiri / Self Metering (status pending & verified)
--  * No 39 - 43: Pengumpul Poin Reward & Penukar Voucher Diskon Listrik
--  * No 44 - 47: Pelanggan Bisnis / UMKM & Sosial (kWh & tagihan tinggi)
--  * No 48 - 50: Pelapor Gangguan Listrik / Pemadaman (Outage Reports)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `password`=VALUES(`password`), `role`=VALUES(`role`);

-- --------------------------------------------------------------------------
-- 2. TABEL: customers (Data Pelanggan PLN)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `tariff_id`=VALUES(`tariff_id`), `nama`=VALUES(`nama`), `alamat`=VALUES(`alamat`), `nomor_telepon`=VALUES(`nomor_telepon`);

-- --------------------------------------------------------------------------
-- 3. TABEL: meter_readings (Baca Meteran Listrik)
-- Catatan: Kolom total_kwh otomatis dihitung oleh MySQL (meteran_akhir - awal)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `meteran_awal`=VALUES(`meteran_awal`), `meteran_akhir`=VALUES(`meteran_akhir`), `status`=VALUES(`status`);

-- --------------------------------------------------------------------------
-- 4. TABEL: bills (Tagihan Rekening Listrik)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `total_biaya`=VALUES(`total_biaya`), `status`=VALUES(`status`), `denda`=VALUES(`denda`), `tanggal_bayar`=VALUES(`tanggal_bayar`);

-- --------------------------------------------------------------------------
-- 5. TABEL: transactions (Riwayat Pembayaran Tagihan & Token Prabayar)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`), `amount`=VALUES(`amount`);

-- --------------------------------------------------------------------------
-- 6. TABEL: reward_claims (Voucher Diskon Hasil Tukar Poin)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);

-- --------------------------------------------------------------------------
-- 7. TABEL: outage_reports (Pengaduan Gangguan Listrik / Pemadaman)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);

SET FOREIGN_KEY_CHECKS=1;
